// src/App.js — ghép các component; Footer đọc hai slice
import { useSelector } from 'react-redux';
import Header from './components/Header';
import Counter from './components/Counter';

function Footer() {
  const mode = useSelector((s) => s.theme.mode);
  const value = useSelector((s) => s.counter.value);
  return <footer id="footer">{mode} · {value} clicks</footer>;
}

export default function App() {
  return (
    <div>
      <Header />
      <Counter />
      <Footer />
    </div>
  );
}

// src/features/theme/themeSlice.js
import { createSlice } from '@reduxjs/toolkit';

const themeSlice = createSlice({
  name: 'theme',
  initialState: { mode: 'light' },
  reducers: {
    toggled(state) {
      state.mode = state.mode === 'light' ? 'dark' : 'light';
    },
  },
});

export const { toggled } = themeSlice.actions;
export const selectMode = (state) => state.theme.mode;
export default themeSlice.reducer;

// src/features/counter/counterSlice.js
import { createSlice } from '@reduxjs/toolkit';

const counterSlice = createSlice({
  name: 'counter',
  initialState: { value: 0 },
  reducers: {
    incremented(state) {
      state.value += 1;
    },
  },
});

export const { incremented } = counterSlice.actions;
export const selectValue = (state) => state.counter.value;
export default counterSlice.reducer;

// src/app/store.js — mỗi slice một khoá trong state gốc
import { configureStore } from '@reduxjs/toolkit';
import themeReducer from '../features/theme/themeSlice';
import counterReducer from '../features/counter/counterSlice';

export const store = configureStore({
  reducer: {
    theme: themeReducer,
    counter: counterReducer,
  },
});

// src/components/Header.js — chỉ đọc theme
import { useDispatch, useSelector } from 'react-redux';
import { selectMode, toggled } from '../features/theme/themeSlice';

export default function Header() {
  const mode = useSelector(selectMode);
  const dispatch = useDispatch();
  return (
    <header id="header" className={mode}>
      <span id="mode">Mode: {mode}</span>
      <button id="toggle-theme" type="button" onClick={() => dispatch(toggled())}>Toggle theme</button>
    </header>
  );
}

// src/components/Counter.js — chỉ đọc counter
import { useDispatch, useSelector } from 'react-redux';
import { incremented, selectValue } from '../features/counter/counterSlice';

export default function Counter() {
  const value = useSelector(selectValue);
  const dispatch = useDispatch();
  return (
    <section>
      <p id="value">{value}</p>
      <button id="inc" type="button" onClick={() => dispatch(incremented())}>+1</button>
    </section>
  );
}

// src/index.js — điểm vào của ứng dụng (đã cho sẵn, không cần sửa)
import React from 'react';
import ReactDOM from 'react-dom/client';
import { Provider } from 'react-redux';
import { store } from './app/store';
import App from './App';

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <Provider store={store}>
        <App />
      </Provider>
  </React.StrictMode>
);
